using System; using System.Collections.Generic; using System.Linq;
namespace Demo.Inventory { public sealed class InventoryService { public const int Capacity=30; readonly InventoryDatabase db; readonly Dictionary<int,InventorySlot> slots=new(); public event Action OnChanged; public InventoryService(InventoryDatabase d){db=d;} public bool AddItem(int id,int amount){if(amount<=0||!db.TryGet(id,out var def))return false;if(slots.TryGetValue(id,out var s)){if(!def.stackable)return false;s.amount=Math.Min(def.maxStack,s.amount+amount);}else{var p=FirstFreePosition();if(p<0)return false;slots[id]=new InventorySlot(id,def.stackable?Math.Min(def.maxStack,amount):1,p);}OnChanged?.Invoke();return true;} public bool RemoveItem(int id,int amount){if(amount<=0||!slots.TryGetValue(id,out var s)||s.amount<amount)return false;s.amount-=amount;if(s.amount==0)slots.Remove(id);OnChanged?.Invoke();return true;} public bool MoveItem(int from,int to){if(to<0||to>=Capacity)return false;var a=slots.Values.FirstOrDefault(x=>x.position==from);if(a==null)return false;var b=slots.Values.FirstOrDefault(x=>x.position==to);a.position=to;if(b!=null)b.position=from;OnChanged?.Invoke();return true;} public int FirstFreePosition(){for(var i=0;i<Capacity;i++)if(slots.Values.All(x=>x.position!=i))return i;return -1;} public int GetAmount(int id)=>slots.TryGetValue(id,out var s)?s.amount:0; public ItemDefinition GetDefinition(int id)=>db.TryGet(id,out var d)?d:null; public List<InventorySlot> GetOrdered(ItemCategory? c=null)=>slots.Values.Where(s=>!c.HasValue||GetDefinition(s.itemId)?.category==c).OrderBy(s=>s.position).ToList(); public List<InventorySaveItem> ToSave()=>slots.Values.Select(s=>new InventorySaveItem{itemId=s.itemId,amount=s.amount,position=s.position}).ToList(); public void Load(IEnumerable<InventorySaveItem> data){slots.Clear();foreach(var x in data??Enumerable.Empty<InventorySaveItem>())if(x.amount>0&&x.position>=0&&x.position<Capacity&&db.TryGet(x.itemId,out _))slots[x.itemId]=new InventorySlot(x.itemId,x.amount,x.position);OnChanged?.Invoke();} } }
